{
  "root": "guide_root",
  "state": {},
  "elements": {
    "guide_root": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "guide_title",
        "hero_section",
        "step1_section",
        "step2_section",
        "step3_section",
        "quick_actions_section",
        "sources_section"
      ]
    },
    "guide_title": {
      "type": "Text",
      "props": {
        "text": "Linux Dual-Boot Preparation Guide",
        "variant": "h1"
      },
      "children": []
    },
    "hero_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "hero_media_stack",
        "hero_intro_text"
      ]
    },
    "hero_media_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "center"
      },
      "children": [
        "hero_image",
        "hero_icon"
      ]
    },
    "hero_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Ubuntu_22.04_LTS_Desktop.png/1200px-Ubuntu_22.04_LTS_Desktop.png",
        "width": 100,
        "height": 100,
        "fit": "contain"
      },
      "children": []
    },
    "hero_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/shield-check.svg"
      },
      "children": []
    },
    "hero_intro_text": {
      "type": "Text",
      "props": {
        "text": "Installing Ubuntu on a Dell XPS 15 requires specific pre-configuration to ensure the Linux kernel can interact with the NVMe drive and Windows remains bootable."
      },
      "children": []
    },
    "step1_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "step1_title",
        "step1_bullet1",
        "step1_bullet2",
        "step1_warning"
      ]
    },
    "step1_title": {
      "type": "Text",
      "props": {
        "text": "1. Safely Manage BitLocker",
        "variant": "h3"
      },
      "children": []
    },
    "step1_bullet1": {
      "type": "Text",
      "props": {
        "text": "• In Windows, search for Manage BitLocker."
      },
      "children": []
    },
    "step1_bullet2": {
      "type": "Text",
      "props": {
        "text": "• Select Suspend protection (this keeps the key but pauses encryption) or Turn off BitLocker (fully decrypts, safest for long-term dual-booting)."
      },
      "children": []
    },
    "step1_warning": {
      "type": "Text",
      "props": {
        "text": "• Warning: Fully decrypting 512GB may take 20-40 minutes."
      },
      "children": []
    },
    "step2_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "step2_title",
        "step2_bullet1",
        "step2_bullet2",
        "step2_bullet3",
        "step2_bullet4"
      ]
    },
    "step2_title": {
      "type": "Text",
      "props": {
        "text": "2. Shrink Windows Partition",
        "variant": "h3"
      },
      "children": []
    },
    "step2_bullet1": {
      "type": "Text",
      "props": {
        "text": "• Right-click the Start button and select Disk Management."
      },
      "children": []
    },
    "step2_bullet2": {
      "type": "Text",
      "props": {
        "text": "• Right-click your (C:) drive and select Shrink Volume."
      },
      "children": []
    },
    "step2_bullet3": {
      "type": "Text",
      "props": {
        "text": "• Enter 153600 (150GB in MB) in the 'Enter the amount of space to shrink' field."
      },
      "children": []
    },
    "step2_bullet4": {
      "type": "Text",
      "props": {
        "text": "• Click Shrink. Leave the resulting space as 'Unallocated'."
      },
      "children": []
    },
    "step3_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "step3_title",
        "step3_bullet1",
        "step3_bullet2",
        "step3_bullet3",
        "step3_bullet4",
        "step3_bullet5"
      ]
    },
    "step3_title": {
      "type": "Text",
      "props": {
        "text": "3. BIOS Configuration",
        "variant": "h3"
      },
      "children": []
    },
    "step3_bullet1": {
      "type": "Text",
      "props": {
        "text": "• Restart and tap F2 to enter BIOS."
      },
      "children": []
    },
    "step3_bullet2": {
      "type": "Text",
      "props": {
        "text": "• SATA Mode: Change from 'RAID On' to AHCI/NVMe. (Note: Windows may require a Safe Mode boot once after this change to update drivers)."
      },
      "children": []
    },
    "step3_bullet3": {
      "type": "Text",
      "props": {
        "text": "• Secure Boot: Disable it."
      },
      "children": []
    },
    "step3_bullet4": {
      "type": "Text",
      "props": {
        "text": "• Fast Boot: Disable it."
      },
      "children": []
    },
    "step3_bullet5": {
      "type": "Text",
      "props": {
        "text": "• Save and Exit BIOS."
      },
      "children": []
    },
    "quick_actions_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "quick_actions_title",
        "download_ubuntu_button",
        "create_usb_button"
      ]
    },
    "quick_actions_title": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "download_ubuntu_button": {
      "type": "Button",
      "props": {
        "label": "Download Ubuntu LTS ISO"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/download/desktop"
          }
        }
      },
      "children": []
    },
    "create_usb_button": {
      "type": "Button",
      "props": {
        "label": "Guide: Create Bootable USB"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/tutorials/create-a-usb-stick-on-windows"
          }
        }
      },
      "children": []
    },
    "sources_section": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "sources_title",
        "ubuntu_guide_button",
        "dell_guide_button"
      ]
    },
    "sources_title": {
      "type": "Text",
      "props": {
        "text": "Sources & Further Reading",
        "variant": "h2"
      },
      "children": []
    },
    "ubuntu_guide_button": {
      "type": "Button",
      "props": {
        "label": "Official Ubuntu Installation Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://ubuntu.com/tutorials/install-ubuntu-desktop"
          }
        }
      },
      "children": []
    },
    "dell_guide_button": {
      "type": "Button",
      "props": {
        "label": "Dell XPS 15 Dual-Boot Specifics"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.dell.com/support/kbdoc/en-us/000131486/how-to-install-ubuntu-and-dual-boot-with-windows-on-a-dell-pc"
          }
        }
      },
      "children": []
    }
  }
}
